parameters.jsCode:
// n8n Code node: Map Apify Places to Account Payload V1
// Mode: Run Once for All Items
//
// Accepts either:
// - one n8n item per Apify place, OR
// - an item whose JSON value contains an array of places.
//
// Outputs provider-neutral account-ingestion records.
// Deep research/scoring is intentionally NOT done here.

function clean(v) {
  if (v === undefined || v === null) return null;
  const s = String(v).trim();
  return s === "" ? null : s;
}

function numericOrNull(v) {
  if (v === undefined || v === null || v === "") return null;
  const n = Number(v);
  return Number.isFinite(n) ? n : null;
}

function boolOrNull(v) {
  return typeof v === "boolean" ? v : null;
}

function countryFromCode(code) {
  const c = clean(code);
  if (!c) return "United States";
  if (c.toUpperCase() === "US") return "United States";
  return c;
}

// Flatten possible response shapes.
let places = [];

for (const item of items) {
  const value = item.json;

  if (Array.isArray(value)) {
    places.push(...value);
  } else if (Array.isArray(value?.data)) {
    places.push(...value.data);
  } else {
    places.push(value);
  }
}

return places
  .filter((p) => p && clean(p.title))
  .map((p) => {
    const lat = numericOrNull(p.location?.lat ?? p.latitude);
    const lng = numericOrNull(p.location?.lng ?? p.longitude);

    return {
      json: {
        company_name: clean(p.title),
        website_url: clean(p.website),

        google_maps_url: clean(p.url),
        country: countryFromCode(p.countryCode),
        state: clean(p.state),
        city: clean(p.city),
        street_address: clean(p.address),
        postal_code: clean(p.postalCode),

        industry: clean(p.categoryName),
        primary_category: clean(p.categoryName),

        company_phone: clean(p.phoneUnformatted ?? p.phone),
        google_rating: numericOrNull(p.totalScore),
        google_review_count: numericOrNull(p.reviewsCount),

        permanently_closed: boolOrNull(p.permanentlyClosed),
        temporarily_closed: boolOrNull(p.temporarilyClosed),

        latitude: lat,
        longitude: lng,

        discovery_source: "apify_google_maps",
        discovery_source_id: clean(p.placeId),
        source_query: clean(p.searchString),

        // The normalize node preserves this record in source_payload.
        source_payload: p,
        is_test_record: false
      }
    };
  });

// n8n Code node: Normalize Account V1.1
// Mode: Run Once for All Items

function clean(value) {
  if (value === undefined || value === null) return null;
  const s = String(value).trim();
  return s === '' ? null : s;
}

function normalizeCompanyName(value) {
  const s = clean(value);
  if (!s) return null;

  return s
    .toLowerCase()
    .replace(/&/g, ' and ')
    .replace(/[^a-z0-9]+/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function normalizeDomain(value) {
  let s = clean(value);
  if (!s) return null;

  s = s.trim().toLowerCase();
  s = s.replace(/^[a-z][a-z0-9+.-]*:\/\//i, '');
  s = s.replace(/^\/\//, '');
  s = s.split(/[/?#]/)[0];

  if (s.includes('@')) s = s.split('@').pop();

  s = s.replace(/:\d+$/, '');
  s = s.replace(/^www\./, '');
  s = s.replace(/\.$/, '');

  if (!s || !s.includes('.') || /\s/.test(s)) return null;
  return s;
}

function slug(value, fallback) {
  const s = clean(value);
  if (!s) return fallback;

  const result = s
    .toLowerCase()
    .replace(/&/g, ' and ')
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '');

  return result || fallback;
}

function numberOrNull(value) {
  if (value === undefined || value === null || value === '') return null;
  const n = Number(value);
  return Number.isFinite(n) ? n : null;
}

function boolOrNull(value) {
  return typeof value === 'boolean' ? value : null;
}

return items.map((item) => {
  const r = item.json || {};

  const companyName =
    clean(r.company_name) ??
    clean(r.title) ??
    clean(r.name);

  if (!companyName) {
    throw new Error('company_name is required for ingestion');
  }

  const websiteUrl =
    clean(r.website_url) ??
    clean(r.website) ??
    clean(r.url);

  const suppliedDomain = clean(r.domain);

  const normalizedDomain =
    normalizeDomain(suppliedDomain) ??
    normalizeDomain(websiteUrl);

  const discoverySource =
    clean(r.discovery_source) ??
    'manual';

  const discoverySourceId =
    clean(r.discovery_source_id) ??
    clean(r.place_id) ??
    clean(r.placeId) ??
    clean(r.source_id);

  const city = clean(r.city);
  const state = clean(r.state);

  let accountKey;

  if (normalizedDomain) {
    accountKey = `domain:${normalizedDomain}`;
  } else if (discoverySourceId) {
    accountKey =
      `source:${slug(discoverySource, 'unknown-source')}:${slug(discoverySourceId, 'unknown-id')}`;
  } else {
    accountKey =
      `fallback:${slug(companyName, 'unknown-company')}:${slug(city, 'unknown-city')}:${slug(state, 'unknown-state')}`;
  }

  return {
    json: {
      account_key: accountKey,

      company_name: companyName,
      normalized_company_name: normalizeCompanyName(companyName),

      domain: normalizedDomain,
      normalized_domain: normalizedDomain,
      website_url: websiteUrl,

      linkedin_url: clean(r.linkedin_url),
      google_maps_url: clean(r.google_maps_url),

      country: clean(r.country) ?? 'United States',
      state,
      city,
      street_address: clean(r.street_address ?? r.address),
      postal_code: clean(r.postal_code),

      discovery_source: discoverySource,
      discovery_source_id: discoverySourceId,
      source_query: clean(r.source_query),

      industry: clean(r.industry),
      employee_band: clean(r.employee_band),
      employee_count_estimate: numberOrNull(r.employee_count_estimate),
      founded_year: numberOrNull(r.founded_year),
      company_type: clean(r.company_type),

      company_phone: clean(r.company_phone),
      primary_category: clean(r.primary_category),
      google_rating: numberOrNull(r.google_rating),
      google_review_count: numberOrNull(r.google_review_count),
      permanently_closed: boolOrNull(r.permanently_closed),
      temporarily_closed: boolOrNull(r.temporarily_closed),
      latitude: numberOrNull(r.latitude),
      longitude: numberOrNull(r.longitude),

      qualification_status: 'normalized',

      // Preserve provider-level data for audit/debugging.
      source_payload: r.source_payload ?? r,

      is_test_record: Boolean(r.is_test_record),
    },
  };
});

return [
  {
    json: {
      processing_run_id: $("Create Processing Run").first().json.id,
      records_received: $("Map Apify Places").all().length,
      records_processed: items.length,
      status: "success",
      completed_at: new Date().toISOString()
    }
  }
];
